import triton
import triton.language as tl
from triton.runtime import driver


@triton.jit
def _erfc_kernel(x_ptr, out_ptr, N, BLOCK: tl.constexpr):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offs < N
    x = tl.load(x_ptr + offs, mask=mask, other=0.0).to(tl.float32)
    y = 1.0 - tl.math.erf(x)
    tl.store(out_ptr + offs, y, mask=mask)


@triton.jit
def _erfc_persistent_kernel(x_ptr, out_ptr, N, BLOCK: tl.constexpr):
    pid = tl.program_id(0)
    stride = tl.num_programs(0) * BLOCK
