def special_erfc(x):
    N = x.numel()
    if N == 0:
        return torch.empty_like(x)

    x_flat = x.contiguous().reshape(-1)
    out_flat = torch.empty_like(x_flat)

    BLOCK = _pick_block(N)
    full_grid = triton.cdiv(N, BLOCK)
    ncores = _vectorcore_count()
    # For very large N, launch one persistent program per vector core and loop,
    # amortizing per-program launch/prologue overhead. For small/mid N keep the
    # one-block-per-program grid so every program does exactly one tile.
    if full_grid > 4 * ncores:
        n_programs = min(2 * ncores, full_grid)
        grid = (n_programs,)
        _erfc_persistent_kernel[grid](x_flat, out_flat, N, BLOCK=BLOCK)
    else:
        grid = (full_grid,)
        _erfc_kernel[grid](x_flat, out_flat, N, BLOCK=BLOCK)
    return out_flat.reshape(x.shape)
